package integrity

// فحوصات قسم الزبائن والشكاوي (11-04). قراءة بس. كل شرط مأخوذ من قاعدة مكتوبة بالكود:
// الهاتف ١١ رقم (validation.ts)، الشكوى المسدودة تاخذ resolvedAt (complaint_repository)،
// تبويب الجي بي اس = CustomerServiceTag + CustomerGpsInfo (customer_repository).

func init() {
	Checks = append(Checks,
		Check{Key: "customer_phone_bad_format", Domain: "customers", Severity: "medium",
			Title:  "زبائن رقم هاتفهم مو ١١ رقم",
			Why:    "الإدخال يرفض أي رقم مو ١١ رقم، فهذني دخلوا من استيراد أو مسار قديم — البحث بالرقم والواتساب ما يلگوهم.",
			Fix:    "نصحّح الرقم (نشيل +964 والمسافات) أو نتصل بالزبون.",
			Count:  `SELECT count(*)::bigint n FROM "Customer" WHERE phone !~ '^[0-9]{11}$'`,
			Sample: `SELECT id, COALESCE("customerCode"::text,'?')||' «'||name||'» phone='||phone info FROM "Customer" WHERE phone !~ '^[0-9]{11}$' ORDER BY "customerCode" LIMIT 20`},
		Check{Key: "customer_duplicate_phone_digits", Domain: "customers", Severity: "high",
			Title:  "نفس الزبون مسجّل أكثر من مرة بصيغة رقم مختلفة",
			Why:    "الرقم فريد بس بالنص — 07701234567 و +9647701234567 يصيرون زبونين، فتتوزع حجوزاته وشكاويه.",
			Fix:    "ندمج الزبونين على السجل الأقدم.",
			Count:  `SELECT count(*)::bigint n FROM (SELECT right(regexp_replace(phone,'\D','','g'),10) k FROM "Customer" WHERE length(regexp_replace(phone,'\D','','g')) >= 10 GROUP BY 1 HAVING count(*) > 1) t`,
			Sample: `SELECT min(id) id, right(regexp_replace(phone,'\D','','g'),10)||' × '||count(*)||': '||string_agg(phone, ' / ') info FROM "Customer" WHERE length(regexp_replace(phone,'\D','','g')) >= 10 GROUP BY right(regexp_replace(phone,'\D','','g'),10) HAVING count(*) > 1 LIMIT 20`},
		Check{Key: "customer_gps_tag_without_info", Domain: "customers", Severity: "medium",
			Title:  "زبون جي بي اس بلا معلومات جهاز",
			Why:    "يطلع بتبويب الجي بي اس بلا رقم جهاز ولا تاريخ انتهاء، فمتابعة التجديد ما تشمله.",
			Fix:    "نعبّي رقم الجهاز وتاريخ الاشتراك، أو نشيل علامة الخدمة.",
			Count:  `SELECT count(DISTINCT t."customerId")::bigint n FROM "CustomerServiceTag" t LEFT JOIN "CustomerGpsInfo" gi ON gi."customerId" = t."customerId" WHERE t.service = 'GPS' AND gi.id IS NULL`,
			Sample: `SELECT DISTINCT c.id, COALESCE(c."customerCode"::text,'?')||' «'||c.name||'» علامة GPS بلا CustomerGpsInfo' info FROM "CustomerServiceTag" t JOIN "Customer" c ON c.id = t."customerId" LEFT JOIN "CustomerGpsInfo" gi ON gi."customerId" = t."customerId" WHERE t.service = 'GPS' AND gi.id IS NULL LIMIT 20`},
		Check{Key: "customer_gps_info_without_tag", Domain: "customers", Severity: "medium",
			Title:  "معلومات جهاز جي بي اس لزبون مو بقائمة الجي بي اس",
			Why:    "التبويب يقرا علامة الخدمة، فالزبون الي عنده جهاز وبلا علامة ما يطلع ولا يجيه تذكير تجديد.",
			Fix:    "نضيف علامة GPS للزبون.",
			Count:  `SELECT count(*)::bigint n FROM "CustomerGpsInfo" gi WHERE NOT EXISTS (SELECT 1 FROM "CustomerServiceTag" t WHERE t."customerId" = gi."customerId" AND t.service = 'GPS')`,
			Sample: `SELECT c.id, COALESCE(c."customerCode"::text,'?')||' «'||c.name||'» جهاز='||COALESCE(gi."gpsNumber",'-') info FROM "CustomerGpsInfo" gi JOIN "Customer" c ON c.id = gi."customerId" WHERE NOT EXISTS (SELECT 1 FROM "CustomerServiceTag" t WHERE t."customerId" = gi."customerId" AND t.service = 'GPS') LIMIT 20`},
		Check{Key: "customer_coords_outside_iraq", Domain: "customers", Severity: "medium",
			Title:  "موقع زبون برّا العراق",
			Why:    "إحداثيات مقلوبة (lat/lng) أو صفر — الكادر يروح لمكان غلط، وتحليل وقت الطريق يطلع كذب.",
			Fix:    "نصحّح الموقع من رابط الخريطة أو نتصل بالزبون.",
			Count:  `SELECT count(*)::bigint n FROM "Customer" WHERE (lat IS NOT NULL AND (lat NOT BETWEEN 29 AND 38 OR lng NOT BETWEEN 38 AND 49)) OR ("mapLatitude" IS NOT NULL AND ("mapLatitude" NOT BETWEEN 29 AND 38 OR "mapLongitude" NOT BETWEEN 38 AND 49))`,
			Sample: `SELECT id, COALESCE("customerCode"::text,'?')||' lat='||COALESCE(lat::text, "mapLatitude"::text,'-')||' lng='||COALESCE(lng::text, "mapLongitude"::text,'-') info FROM "Customer" WHERE (lat IS NOT NULL AND (lat NOT BETWEEN 29 AND 38 OR lng NOT BETWEEN 38 AND 49)) OR ("mapLatitude" IS NOT NULL AND ("mapLatitude" NOT BETWEEN 29 AND 38 OR "mapLongitude" NOT BETWEEN 38 AND 49)) LIMIT 20`},
		Check{Key: "customer_false_claim_without_date", Domain: "customers", Severity: "low",
			Title:  "بلاغات كاذبة محسوبة بلا تاريخ",
			Why:    "العدّاد يرتفع ويا التاريخ بنفس الخطوة — بلا تاريخ ما نعرف إذا البلاغ قديم أو جديد.",
			Fix:    "نراجع البلاغ ونعبّي تاريخه أو نصفّر العدّاد.",
			Count:  `SELECT count(*)::bigint n FROM "Customer" WHERE "falseClaimCount" > 0 AND "lastFalseClaimAt" IS NULL`,
			Sample: `SELECT id, COALESCE("customerCode"::text,'?')||' بلاغات='||"falseClaimCount" info FROM "Customer" WHERE "falseClaimCount" > 0 AND "lastFalseClaimAt" IS NULL LIMIT 20`},
		Check{Key: "complaint_closed_without_resolved_at", Domain: "customers", Severity: "high",
			Title:  "شكاوي مسدودة بلا تاريخ حل",
			Why:    "كل مسارات السد تعبّي resolvedAt — بلاه مدة الحل ومعيار «حل المشاكل» ما يحسبونها.",
			Fix:    "نعبّي resolvedAt من آخر تعديل للشكوى.",
			Count:  `SELECT count(*)::bigint n FROM "Complaint" WHERE status::text IN ('RESOLVED','CLOSED') AND "resolvedAt" IS NULL AND "settledLegacyAt" IS NULL`,
			Sample: `SELECT id, status::text||' بلا resolvedAt — انفتحت '||("createdAt"::date)::text info FROM "Complaint" WHERE status::text IN ('RESOLVED','CLOSED') AND "resolvedAt" IS NULL AND "settledLegacyAt" IS NULL ORDER BY "createdAt" DESC LIMIT 20`},
		Check{Key: "complaint_open_with_resolved_at", Domain: "customers", Severity: "medium",
			Title:  "شكاوي مفتوحة وعليها تاريخ حل",
			Why:    "انفتحت من جديد وبقى تاريخ الحل القديم — التقارير تحسبها محلولة وهي بعدها مفتوحة.",
			Fix:    "نصفّر resolvedAt للشكاوي المفتوحة.",
			Count:  `SELECT count(*)::bigint n FROM "Complaint" WHERE status::text IN ('NEW','IN_PROGRESS') AND "resolvedAt" IS NOT NULL`,
			Sample: `SELECT id, status::text||' resolvedAt='||("resolvedAt"::date)::text info FROM "Complaint" WHERE status::text IN ('NEW','IN_PROGRESS') AND "resolvedAt" IS NOT NULL LIMIT 20`},
		Check{Key: "complaint_open_assigned_inactive", Domain: "customers", Severity: "high",
			Title:  "شكاوي مفتوحة مكلّف بيها موظف مو فعّال",
			Why:    "الشكوى تضل عند شخص ما يشوفها، والزبون ينتظر.",
			Fix:    "نعيد التكليف لمهندس جودة فعّال.",
			Count:  `SELECT count(*)::bigint n FROM "Complaint" c JOIN "Employee" e ON e.id = c."assignedToEmployeeId" WHERE c.status::text IN ('NEW','IN_PROGRESS') AND e.status::text <> 'ACTIVE'`,
			Sample: `SELECT c.id, 'مكلّف: '||e.name||' ('||e.status::text||') منذ '||(c."createdAt"::date)::text info FROM "Complaint" c JOIN "Employee" e ON e.id = c."assignedToEmployeeId" WHERE c.status::text IN ('NEW','IN_PROGRESS') AND e.status::text <> 'ACTIVE' LIMIT 20`},
		Check{Key: "complaint_dropped_but_open", Domain: "customers", Severity: "medium",
			Title:  "شكاوي «سقطت» وبعدها مفتوحة",
			Why:    "السقوط (٣ مرات ما رد) يسد الشكوى بنفس الخطوة — مفتوحة ويا علامة السقوط يعني تناقض يربك العدّادات.",
			Fix:    "إما نسدّها أو نشيل علامة السقوط إذا رجع الزبون رد.",
			Count:  `SELECT count(*)::bigint n FROM "Complaint" WHERE "droppedNoAnswerAt" IS NOT NULL AND status::text IN ('NEW','IN_PROGRESS')`,
			Sample: `SELECT id, status::text||' سقطت '||("droppedNoAnswerAt"::date)::text info FROM "Complaint" WHERE "droppedNoAnswerAt" IS NOT NULL AND status::text IN ('NEW','IN_PROGRESS') LIMIT 20`},
	)
}
